    return Invoice("inv_1","cus_1",lines=[LineItem("Seat",1,Decimal("50.00"))],status=status)

# valid
print(issue_credit_note(inv(), Decimal("10.00"), "goodwill"))
# zero / negative
for a in (Decimal("0"), Decimal("-1")):
    try: issue_credit_note(inv(), a, "x")
    except BillingError as e: print("err", e.code)
